import{isCountryCapturable,isIpCountryCapturable}from"../geo-permission";const checkoutFrom=e=>({id:"chk_1",ip_geo_address:e?{country:e}:null});describe("isIpCountryCapturable",(()=>{it("captures everywhere when the list is empty",(()=>{expect(isIpCountryCapturable(checkoutFrom("US"),[])).toBe(!0),expect(isIpCountryCapturable(checkoutFrom(null),[])).toBe(!0),expect(isIpCountryCapturable(null,[])).toBe(!0)})),it("matches when the IP country is listed",(()=>{expect(isIpCountryCapturable(checkoutFrom("IN"),["IN","BR"])).toBe(!0)})),it("rejects when the IP country is not listed",(()=>{expect(isIpCountryCapturable(checkoutFrom("US"),["IN","BR"])).toBe(!1)})),it("fails closed when the IP country is unknown",(()=>{expect(isIpCountryCapturable(checkoutFrom(null),["IN"])).toBe(!1),expect(isIpCountryCapturable(null,["IN"])).toBe(!1),expect(isIpCountryCapturable({id:"chk_1",ip_geo_address:"addr_1"},["IN"])).toBe(!1)}))})),describe("isCountryCapturable",(()=>{it("matches case-insensitively",(()=>{expect(isCountryCapturable("us",["US","CA"])).toBe(!0),expect(isCountryCapturable("US",["us"])).toBe(!0)})),it("captures everywhere when the list is empty",(()=>{expect(isCountryCapturable(null,[])).toBe(!0)})),it("fails closed for a missing or unlisted code",(()=>{expect(isCountryCapturable(null,["US"])).toBe(!1),expect(isCountryCapturable("FR",["US"])).toBe(!1)}))}));